/* Throwaway design study: eight complete Doc Keeper screen sets, using in-memory fixtures.
   Question: which hierarchy makes finding, showing and keeping documents easiest? */
const variants = [
 {id:'apple',name:'Apple · Fluid glass',short:'Fluid glass',tag:'Light, layered, familiar',description:'A calm library with translucent controls, generous spacing, and responsive motion.',principle:'Familiar at first touch.',copy:'Documents take the lead. Soft materials separate navigation from content; a floating tab bar keeps everyday actions within reach.',colors:['#f1f3f9','#dce8ff','#0960c5','#1c2433']},
 {id:'swiss',name:'Swiss · Clear index',short:'Clear index',tag:'Precise, quiet, direct',description:'An evolution of Doc Keeper’s existing Swiss identity, built around a clear document index.',principle:'Find it. Show it.',copy:'A consistent left edge, ruled sections and explicit labels make the collection easy to scan. Document previews keep their real proportions.',colors:['#ffffff','#f5f1e8','#b38b6d','#111111']},
 {id:'wallet',name:'Wallet · In your pocket',short:'In your pocket',tag:'Tactile, focused, personal',description:'A pocket-sized document wallet with stacked previews and fast access to your essentials.',principle:'Keep the essentials close.',copy:'Pinned documents form a tangible stack. A quieter list holds the rest, so the document you need at a counter is always the first thing you see.',colors:['#e8ede8','#d8e5df','#315f49','#243a32']},
 {id:'focus',name:'Focus · Night desk',short:'Night desk',tag:'Compact, dark, efficient',description:'A compact document workspace with search first, visible metadata, and low-glare surfaces.',principle:'Less hunting. More context.',copy:'A top navigation strip leaves the bottom free for actions. Compact rows show document status without opening each one, even in a larger collection.',colors:['#18202b','#222e3b','#a9d4f3','#eff4fa']},
 {id:'guide',name:'Guide · Everyday ease',short:'Everyday ease',tag:'Friendly, spacious, guided',description:'A welcoming, task-led design with larger controls and clear next steps for everyday use.',principle:'Always a clear next step.',copy:'Start with the action that matters. Simple explanations, spacious rows and reassuring feedback help people keep documents without learning a system.',colors:['#f4f2fb','#e9e3f7','#6550a0','#352d51']},
 {id:'folio',name:'Folio · Paper tabs',short:'Paper tabs',tag:'Organised, tactile, browsable',description:'A tag-first filing cabinet with expandable document groups and tabbed paper surfaces.',principle:'A place for every document.',copy:'Browse by a familiar tag instead of scanning a long library. Expand a drawer to find its documents; labels and counts keep the collection legible.',colors:['#edf4f3','#ffffff','#176b69','#183c40']},
 {id:'agenda',name:'Agenda · Ahead of time',short:'Ahead of time',tag:'Timely, ordered, reassuring',description:'An expiry-led planner that puts upcoming renewals before the rest of your collection.',principle:'Know what needs you next.',copy:'Documents follow their expiry dates, not the order they were added. A clear date rail gives renewals a place without turning your vault into a busy dashboard.',colors:['#f4f6fc','#e3eafa','#304e9b','#202e4f']},
 {id:'glance',name:'Glance · Ready to show',short:'Ready to show',tag:'Large, immediate, one-handed',description:'An accessible quick-access board with large pinned shortcuts and one-tap presentation.',principle:'One tap at the counter.',copy:'Pinned documents become large, named shortcuts that open directly in presentation mode. A separate library list keeps editing and occasional documents close by.',colors:['#fcf8f1','#f1e6d2','#82501f','#392d20']}
];
const screens = [ ['home','Documents'],['empty','Empty library'],['document','Document'],['pdf','PDF viewer'],['present','Show at counter'],['add','Add document'],['edit','Edit document'],['notes','Notes'],['note','Edit note'],['folders','Folders'],['tags','Tags'],['settings','Settings'],['export','Export backup'],['import','Import backup'],['paywall','Unlimited'],['privacy','Privacy'],['lock','App lock'],['share','Shared document'],['problems','Problems'],['crash','Crash prompt'],['boot','Opening app'],['recovery','Recovery'] ];
const paths={close:'path d="M5 5l14 14M19 5 5 19"',search:'circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"',grid:'rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"',note:'path d="M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h5"',settings:'path d="m9 3-1 3-3 1-2 4 2 2 1 4 4 3 3-1 4-1 3-4-1-3-1-4-4-2z"/><circle cx="12" cy="12" r="3"',plus:'path d="M12 5v14M5 12h14"',back:'path d="m14 6-6 6 6 6"',next:'path d="m9 6 6 6-6 6"',shield:'path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6zM8 12l3 3 5-6"',pin:'path d="m8 3 8 0-1 6 4 4H5l4-4zM12 13v8"',folder:'path d="M3 6h7l2 2h9v12H3z"',tag:'path d="M3 3h8l10 10-8 8L3 11z"/><circle cx="7" cy="7" r="1"',doc:'path d="M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h5"',lock:'rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"',clock:'circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"',check:'path d="m5 12 4 4L19 6"',flip:'path d="M5 8h13l-4-4M19 16H6l4 4M19 8v4M5 16v-4"',share:'path d="M12 16V3m-4 4 4-4 4 4M5 12v9h14v-9"',camera:'path d="M3 7h5l2-3h4l2 3h5v14H3z"/><circle cx="12" cy="13" r="4"',eye:'path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"',backup:'path d="M7 17H5a4 4 0 0 1 0-8 7 7 0 0 1 14 0 4 4 0 0 1 0 8h-2M12 21V11m-4 4 4-4 4 4"',download:'path d="M12 3v13m-4-4 4 4 4-4M4 17v4h16v-4"',user:'circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"',trash:'path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"',more:'circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"',star:'path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><${paths[n]||paths.doc}/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const originalDocs=[{id:1,name:'Emirates ID',kind:'Resident identity',issuer:'United Arab Emirates',person:'Alex Morgan',number:'784 •••• •••• 0421',tag:'ID',color:'',expiry:'24 Nov 2026',pinned:true},{id:2,name:'Driving licence',kind:'Driving licence',issuer:'Roads & Transport Authority',person:'Alex Morgan',number:'DXB •••• 7812',tag:'ID',color:'blue',expiry:'18 Aug 2028',pinned:true},{id:3,name:'Health insurance',kind:'Health coverage',issuer:'Carewell Health',person:'Alex Morgan',number:'CW •••• 6103',tag:'Insurance',color:'rose',expiry:'03 Mar 2027',pinned:false},{id:4,name:'Apartment contract',kind:'Tenancy agreement',issuer:'Home documents',person:'Alex Morgan',number:'PDF · 4 pages',tag:'Home',color:'gold',expiry:'30 Jun 2027',pinned:false,pdf:true}];
let docs=structuredClone(originalDocs),notes=[{title:'For the next trip',body:'Passport, residency and travel insurance.\n\nCheck the expiry dates before booking.',pinned:true},{title:'Insurance helpline',body:'Keep the policy number handy when calling. Coverage renews in March.',pinned:false}],folders=['Personal','Travel','Home'],tags=['ID','Insurance','Home','Travel'];
let params=new URLSearchParams(location.search),variant=variants.some(v=>v.id===params.get('variant'))?params.get('variant'):'apple',screen=screens.some(s=>s[0]===params.get('screen'))?params.get('screen'):'home';
let selected=1,query='',filter='All',back=false,details=false,importStep=0,pdfPage=1,selectedNote=0,settings={lock:true,brightness:true,swipe:false,blur:false},toastTimer;
let documentDraft=null,noteDraft=null;
const sheetScreens=new Set(['add','edit','share','note','tags','export','import','paywall','privacy','problems']);
const sheetOrigins={add:'home',edit:'document',share:'home',note:'notes',tags:'settings',export:'settings',import:'settings',paywall:'settings',privacy:'settings',problems:'settings'};
let baseScreen=sheetScreens.has(screen)?(screens.some(s=>s[0]===params.get('from'))&&!sheetScreens.has(params.get('from'))?params.get('from'):sheetOrigins[screen]):null;
const current=()=>docs.find(d=>d.id===selected)||docs[0]||originalDocs[0];
const button=(text,action,style='primary',ic='')=>`<button class="${style}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const ib=(name,action,label)=>`<button class="icon-button" data-action="${action}" aria-label="${label}">${icon(name)}</button>`;
function go(to){captureDraft();if(to==='pdf')selected=4;if(sheetScreens.has(to)){baseScreen=baseScreen||(!sheetScreens.has(screen)?screen:sheetOrigins[to]);}else baseScreen=null;screen=to;query='';details=false;back=false;render();}
function closeSheet(){if(!baseScreen)return;captureDraft();screen=baseScreen;baseScreen=null;render()}
function captureDraft(){if(['add','edit','share'].includes(screen)&&document.querySelector('[name="name"]')){documentDraft=Object.fromEntries(new FormData(document.querySelector('#document-form')))}if(screen==='note'&&document.querySelector('#note-form'))noteDraft=Object.fromEntries(new FormData(document.querySelector('#note-form')))}
function setVariant(id){captureDraft();variant=id;render()}
function paper(d,reverse=false){return `<div class="paper ${d.color}"><span class="issuer">${esc(d.issuer)}</span><span class="doc-kind">${reverse?'Document information':esc(d.kind)}</span><span class="person">${reverse?'Signature on file':esc(d.person)}</span><span class="number">${reverse?'Valid until '+esc(d.expiry):esc(d.number)}</span><div class="portrait">${icon(reverse?'shield':'user')}</div><span class="sample">Fictional sample · Not valid</span></div>`}
function docCard(d,list=false){return `<button class="document ${list?'list':''}" data-open="${d.id}">${list?`<span class="mini-paper">${icon(d.pdf?'doc':'user')}</span>`:paper(d)}<span class="doc-info"><span class="doc-title">${esc(d.name)}</span><span class="doc-meta">${esc(d.tag)}${d.id===1?' · Expires in 9 days':d.pdf?' · PDF, 4 pages':' · '+esc(d.expiry)}</span></span>${list?icon('next'):''}</button>`}
function nav(){return `<nav class="bottom-nav" aria-label="App navigation">${[['home','grid','Documents'],['notes','note','Notes'],['folders','folder','Folders'],['settings','settings','Settings']].map(([s,i,l])=>`<button data-go="${s}" class="${s===screen?'active':''}" ${s===screen?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav>`}
function header(title,sub='',root=false){return `<header class="app-header">${sheetScreens.has(screen)?'':root?'':ib('back','go:'+({document:'home',pdf:'home',present:current().pdf?'pdf':'document',notes:'home',empty:'home',crash:'home',recovery:'home'}[screen]||'settings'),'Go back')}<div class="heading"><h2>${title}</h2>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${sheetScreens.has(screen)?ib('close','close-sheet','Close sheet'):root?ib(screen==='settings'?'lock':'settings',screen==='settings'?'go:lock':'go:settings',screen==='settings'?'Lock demo':'Settings'):''}</header>`}
const search=placeholder=>`<div class="search">${icon('search')}<input id="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}" autocomplete="off"></div>`;
const footer=(label,action,secondary='')=>`<div class="action-footer">${secondary?button('Cancel',sheetScreens.has(screen)?'close-sheet':'go:home','secondary'):''}${button(label,action)}</div>`;
const row=(i,title,sub,action)=>`<button class="row" data-action="${action}">${icon(i)}<span><strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</span>${icon('next')}</button>`;
const toggle=(key,title,sub)=>`<label class="row">${icon(key==='lock'?'lock':'eye')}<span><strong>${title}</strong><small>${sub}</small></span><input class="toggle" type="checkbox" data-setting="${key}" aria-label="${title}" ${settings[key]?'checked':''}></label>`;
const field=(label,name,value='',type='text',hint='')=>`<label class="form-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='password'?'autocomplete="new-password"':''}>${hint?`<small>${hint}</small>`:''}</label>`;
function home(){const found=docs.filter(d=>(filter==='All'||filter==='Expiring'&&d.id===1||d.tag===filter)&&`${d.name} ${d.number} ${d.tag} ${d.person}`.toLowerCase().includes(query.toLowerCase()));let content=search('Search names, numbers or text')+`<div class="chips">${['All','ID','Insurance','Home','Expiring'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div>`;
if(!query&&filter==='All'){
 if(variant==='apple')content+=`<div class="section-top"><h3>Pinned for quick access</h3>${icon('pin')}</div>`+docs.filter(d=>d.pinned).map(d=>docCard(d)).join('')+`<div class="section-top"><h3>All documents</h3><span class="muted">${docs.length} documents</span></div>`+docs.filter(d=>!d.pinned).map(d=>docCard(d,true)).join('');
 if(variant==='swiss')content+=`<div class="home-summary"><div class="summary-tile"><strong>${docs.length.toString().padStart(2,'0')}</strong><span>Documents kept</span></div><div class="summary-tile"><strong>01</strong><span>Expiring soon</span></div></div><div class="compact-toolbar"><span>Document / tag</span><span>Expiry date</span></div>`+docs.map(d=>docCard(d,true)).join('')+`<div class="notice">${icon('shield')}Encrypted on this phone. Always yours.</div>`;
 if(variant==='wallet')content+=`<div class="section-top"><h3>Your everyday essentials</h3><span class="muted">${docs.filter(d=>d.pinned).length} pinned</span></div><div class="wallet-stack">${docCard(docs.find(d=>d.pinned)||docs[0])}</div><div class="notice warning">${icon('clock')}<span><strong>Emirates ID expires soon</strong>9 days left. A reminder is set.</span></div><h3>Also in your wallet</h3>`+docs.slice(1).map(d=>docCard(d,true)).join('');
 if(variant==='focus')content+=`<div class="notice warning">${icon('clock')}<span><strong>1 document needs attention</strong>Emirates ID expires in 9 days</span></div><div class="compact-toolbar"><span>Name · Type · Expiry</span><span>${docs.length} documents</span></div>`+docs.map(d=>docCard(d,true)).join('')+`<h3>Quick tools</h3><div class="group">${row('backup','Export backup','Last backup: 12 Nov','go:export')}${row('tag','Manage tags',`${tags.length} tags`,'go:tags')}</div>`;
 if(variant==='guide')content+=`<div class="guide-welcome">${icon('shield')}<h3>A safe place for<br>your important things.</h3><p>Keep a photo or PDF. Find it whenever you need it.</p>${button('Add a document','go:add','primary','plus')}</div><div class="section-top"><h3>Ready when you need them</h3></div>`+docs.map(d=>docCard(d,true)).join('');
 if(variant==='folio')content+=`<div class="cabinet-intro"><span>${icon('folder')}</span><div><h3>Your document drawers</h3><p>Open a tag to find what’s inside.</p></div></div><div class="cabinet">`+[...new Set(docs.map(d=>d.tag))].map((tag,i)=>{const group=docs.filter(d=>d.tag===tag);return `<details class="drawer" ${i===0?'open':''}><summary><span class="drawer-tab">${icon('tag')}${esc(tag)}</span><span class="drawer-count">${group.length} ${group.length===1?'document':'documents'}</span>${icon('next')}</summary><div class="drawer-documents">${group.map(d=>docCard(d,true)).join('')}</div></details>`}).join('')+`</div><button class="text-button" data-go="tags">Manage your tags</button><div class="notice">${icon('shield')}Every drawer stays encrypted on your phone.</div>`;
 if(variant==='agenda'){const dated=docs.filter(d=>Number.isFinite(Date.parse(d.expiry))).sort((a,b)=>Date.parse(a.expiry)-Date.parse(b.expiry)),undated=docs.filter(d=>!Number.isFinite(Date.parse(d.expiry)));content+=`<div class="planner-banner">${icon('clock')}<div><strong>Renewals, in good time.</strong><p>Expiry dates and reminders in one place.</p></div></div><div class="section-top"><h3>Coming up</h3><span class="muted">${dated.length} dated documents</span></div><div class="expiry-timeline">`+dated.map((d,i)=>`<div class="expiry-entry ${i===0?'next-expiry':''}"><div class="date-rail"><strong>${esc(new Date(d.expiry).getDate())}</strong><span>${esc(new Date(d.expiry).toLocaleDateString('en-GB',{month:'short',year:'numeric'}))}</span></div><div class="expiry-body">${docCard(d,true)}<span class="expiry-caption">${i===0?'Next expiry · ':''}Reminder 14 days before</span></div></div>`).join('')+`</div>`+(undated.length?`<h3>No expiry date</h3>`+undated.map(d=>docCard(d,true)).join(''):'');}
 if(variant==='glance'){const pinned=docs.filter(d=>d.pinned);content+=`<div class="section-top"><h3>Show a pinned document</h3>${icon('pin')}</div><p class="quick-hint">Tap once. Ready for the counter.</p><div class="quick-board">`+(pinned.length?pinned.map(d=>`<button class="show-shortcut" data-present="${d.id}"><span class="shortcut-icon">${icon(d.pdf?'doc':'user')}</span><strong>${esc(d.name)}</strong><span>Show at counter ${icon('next')}</span></button>`).join(''):`<p class="muted">Open a document and pin it to add a shortcut here.</p>`)+`</div><div class="section-top"><h3>Your library</h3><span class="muted">${docs.length} documents</span></div>`+docs.map(d=>docCard(d,true)).join('')+`<div class="quick-tools">${button('Add document','go:add','primary','plus')}${button('Open notes','go:notes','secondary','note')}</div>`;}
}else content+=`<div class="section-top"><h3>${query?'Search results':esc(filter)}</h3><span class="muted">${found.length} documents</span></div>`+(found.length?found.map(d=>docCard(d,true)).join(''):`<div class="hero-center"><div class="hero-icon">${icon('search')}</div><h3>No matching documents</h3><p>Try a name, number or another tag.</p>${button('Clear filters','clear-search','secondary')}</div>`);
return header(variant==='wallet'?'Your wallet':variant==='focus'?'Document desk':variant==='guide'?'Hello, Alex':variant==='folio'?'Your collection':variant==='agenda'?'Expiry planner':variant==='glance'?'Ready to show':'Documents',variant==='swiss'?'Private by design. Available offline.':'Everything you need, kept close.',true)+`<div class="content">${content}</div>`+(['guide','glance'].includes(variant)?'':`<button class="add-button" data-action="go:add" aria-label="Add document">${icon('plus')}</button>`)+nav()}
function editor(){let isNew=screen!=='edit',d=documentDraft||(!isNew?current():{name:'',tag:'ID',expiry:''});return header(screen==='share'?'Keep this document':isNew?'Add document':'Edit document',screen==='share'?'Shared from another app':'Photos or a PDF, kept on your phone')+`<div class="content"><form id="document-form"><div class="two-col"><button class="upload" type="button" data-action="upload:Front">${icon('camera')}<span>${isNew?'Add front':'Replace front'}</span></button><button class="upload" type="button" data-action="upload:Back">${icon('plus')}<span>Add back (optional)</span></button></div><button type="button" class="text-button" data-action="upload:PDF">Choose a PDF instead · Up to 10 MB</button>${field('Document name','name',d.name,'text','Give it a name you can find quickly.')}<label class="form-field">Tag<select name="tag">${tags.map(t=>`<option ${d.tag===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="form-field">Folder<select name="folder"><option>No folder</option>${folders.map(f=>`<option>${esc(f)}</option>`).join('')}</select></label>${field('Expiry date (optional)','expiry',d.expiry&&/^\d{4}-/.test(d.expiry)?d.expiry:!isNew?'2026-11-24':'','date')}${field('Remind me before expiry','reminder','14','number','Days before expiry. The reminder stays on this phone.')}<div class="group">${toggle('blur','Hide preview','Blur this document in the library')}</div>${!isNew?button('Delete document','delete-document','danger'):''}</form></div>${footer(isNew?'Keep document':'Save changes','save-document',true)}`}
function documentView(){const d=current();return header(esc(d.name),d.pdf?'PDF document · 4 pages':esc(d.tag)+' · Personal')+`<div class="content"><div class="segmented"><button data-action="view:document" class="${!details?'selected':''}" aria-pressed="${!details}">Document</button><button data-action="view:details" class="${details?'selected':''}" aria-pressed="${details}">Details & text</button></div>${details?`<h3>Document details</h3><div class="info-pair"><span>Name</span><strong>${esc(d.person)}</strong></div><div class="info-pair"><span>Document number</span><strong>${esc(d.number)}</strong></div><div class="info-pair"><span>Valid until</span><strong>${esc(d.expiry)}</strong></div><h3>Document text</h3><p class="muted">${esc(d.issuer)}<br>${esc(d.kind)}<br>${esc(d.person)}<br>${esc(d.number)}<br>Read on your phone. Searchable, even offline.</p>${button('Save document text','save-text','secondary')}`:`<div class="detail-paper">${paper(d,back)}</div><div class="section-top"><span class="muted">${back?'Back':'Front'} · Tap flip to see the other side</span><button class="text-button" data-action="flip">${icon('flip')} Flip</button></div>${d.id===1?`<div class="notice warning">${icon('clock')}<span><strong>Expires in 9 days</strong>24 November 2026 · Reminder on</span></div>`:''}<div class="chips"><button class="chip" data-go="tags">${esc(d.tag)}</button><span class="badge">Encrypted on device</span></div>`}<div class="group">${row('pin',d.pinned?'Unpin document':'Pin for quick access','Show it first in your library','pin')}${row('share','Share document','Choose a photo or PDF','share-document')}${row('doc','Edit document','Name, tags and expiry date','go:edit')}</div></div>${footer('Show at counter','go:present')}`}
function pdfView(){return header('Apartment contract',`PDF · Page ${pdfPage} of 4`)+`<div class="content"><div class="pdf-page"><span class="muted">Fictional sample document</span><h3>${['Tenancy agreement','Terms of occupancy','Payment schedule','Signatures'][pdfPage-1]}</h3><p>Alex Morgan<br>Residence 204 · Dubai</p><hr><p>This agreement records the terms of the tenancy and the responsibilities of the parties.</p>${Array.from({length:8},(_,i)=>`<div class="pdf-rule ${i%3===2?'short':''}"></div>`).join('')}<p class="muted">Page ${pdfPage} / 4 · Sample only</p></div><div class="section-top">${ib('back','pdf:previous','Previous PDF page')}<span class="muted">Page ${pdfPage} of 4</span>${ib('next','pdf:next','Next PDF page')}</div>${button('Use this page as cover','cover','secondary')}</div>${footer('Show at counter','go:present')}`}
function settingsView(){return header('Settings','Your vault, your preferences.',true)+`<div class="content"><h3>Security & display</h3><div class="group">${toggle('lock','App lock','Use your fingerprint, face or device passcode')}${toggle('brightness','Full brightness at counter','Make your document easier to read')}${toggle('swipe','Vertical swipe','Swipe up to change document sides')}</div><h3>Backup</h3><div class="group">${row('backup','Export backup','Last backup: 12 November 2026','go:export')}${row('download','Import backup','Restore from an encrypted file','go:import')}</div><h3>Organise</h3><div class="group">${row('tag','Manage tags',`${tags.length} tags`,'go:tags')}${row('folder','Manage folders',`${folders.length} folders`,'go:folders')}</div><h3>Doc Keeper</h3><div class="group">${row('star','Unlimited documents',`${docs.length} of 10 free documents used`,'go:paywall')}${row('download','App updates','Version 1.0.0 · Check for updates','updates')}${row('shield','Privacy','No account. No server. No tracking.','go:privacy')}${row('doc','Problems','View and share a technical report','go:problems')}</div></div>`+nav()}
function notesView(){let found=notes.map((n,i)=>({...n,index:i})).filter(n=>(n.title+' '+n.body).toLowerCase().includes(query.toLowerCase()));return header('Notes','A little space for what matters.',true)+`<div class="content">${search('Search notes')}${found.length?found.map(n=>`<button class="note-card" data-note="${n.index}"><small>${n.pinned?'Pinned · ':''}Today</small><strong>${esc(n.title||'Untitled note')}</strong><p>${esc(n.body).replace(/\n/g,'<br>')}</p></button>`).join(''):'<p class="muted">No notes found. Try another search or add a note.</p>'}</div>${footer('Add a note','new-note')}`+nav()}
function noteView(){const n=noteDraft||notes[selectedNote]||{title:'',body:''};return header('Edit note','Changes stay in this demo until reset')+`<div class="content"><form id="note-form">${field('Title (optional)','title',n.title)}<label class="form-field">Note<textarea name="body" style="min-height:290px">${esc(n.body)}</textarea></label></form><div class="section-top"><button class="text-button" data-action="pin-note">${notes[selectedNote]?.pinned?'Unpin note':'Pin note'}</button><button class="danger" style="width:auto" data-action="delete-note">Delete note</button></div></div>${footer('Done','save-note')}`}
function organise(kind){let isTags=kind==='tags',items=isTags?tags:folders;return header(isTags?'Tags':'Folders',isTags?'Give documents more than one way to belong.':'A simple home for related documents.',!isTags)+`<div class="content"><div class="group">${items.map((name,i)=>`<div class="row">${icon(isTags?'tag':'folder')}<span><strong>${esc(name)}</strong><small>${docs.filter(d=>isTags?d.tag===name:name==='Personal').length} documents</small></span>${ib('more',`manage:${kind}:${i}`,`Manage ${esc(name)}`)}</div>`).join('')}</div><div class="notice">${icon('doc')}Removing a ${isTags?'tag':'folder'} keeps its documents in your library.</div></div>${footer(isTags?'Create tag':'Create folder',`new:${kind}`)}${isTags?'':nav()}`}
function exportView(){return header('Export backup','A private copy you control.')+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('backup')}</div><h3>A spare key<br>to your documents.</h3><p>Keep an encrypted copy somewhere safe, ready for your next phone.</p></div><div class="notice">${icon('doc')}<span><strong>${docs.length} documents · ${notes.length} notes</strong>Photos, PDFs and details included</span></div><form id="backup-form">${field('Backup passphrase','passphrase','','password','Use at least 8 characters in this demo.')}${field('Confirm passphrase','confirm','','password')}</form><p class="muted">Keep your passphrase safe. It cannot be recovered if you forget it.</p></div>${footer('Create encrypted backup','export-backup')}`}
function importView(){return header('Import backup','Bring your documents back.')+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('download')}</div><h3>${['Choose your backup.','Unlock your backup.','Ready to bring it back.'][importStep]}</h3><p>${['Select the encrypted backup you saved from Doc Keeper.','Use the passphrase you chose when you exported this backup.','4 documents and 2 notes found in this sample backup.'][importStep]}</p></div>${importStep===0?`<button class="upload" data-action="pick-backup">${icon('folder')}Choose sample backup.dkbackup</button><p class="muted">Prototype: opens a sample backup; no files are read.</p>`:importStep===1?`<div class="notice">${icon('lock')}DocKeeper-12Nov.dkbackup</div><form id="import-form">${field('Backup passphrase','passphrase','','password','Demo passphrase: keeperdemo')}</form>`:`<div class="notice">${icon('shield')}Add documents and skip duplicates. Your current library stays in place.</div>${button('Replace current library','replace-backup','danger')}<p class="muted">Replacing removes the current sample library first.</p>`}</div>${importStep?footer(importStep===1?'Unlock backup':'Add to my library',importStep===1?'unlock-backup':'merge-backup'):''}`}
function paywall(){return header('Unlimited documents')+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('star')}</div><h3>Room for<br>everything important.</h3><p>Keep more than 10 documents with a one-time purchase. No subscription.</p></div><div class="group">${row('check','Unlimited documents','All your photos and PDFs, together','info:Unlimited documents')}${row('shield','The same private vault','Everything stays on this phone','info:Always private')}${row('lock','Your documents stay yours','Existing documents are never locked','info:Your documents stay accessible')}</div><p class="muted">Connect to the store to see your local price. This prototype does not make purchases.</p>${button('Restore purchase','restore-purchase','secondary')}</div>${footer('Check price','check-price')}`}
function privacy(){return header('Privacy','A vault without an account.')+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('shield')}</div><h3>Only on your phone.<br>Only in your hands.</h3></div><h3>Your documents stay here</h3><p class="muted">Photos, PDFs, notes and details are encrypted on your phone. Doc Keeper has no account, no server, no ads and no analytics.</p><h3>Text is read on your device</h3><p class="muted">Document text is read locally so you can search it. Nothing is sent to a cloud service.</p><h3>You choose what leaves</h3><p class="muted">Documents leave only when you choose to share them or export a backup. A technical report is shared only when you choose to send it.</p><h3>Occasional connections</h3><p class="muted">Checking for app updates and viewing, buying or restoring a purchase use the internet.</p><div class="notice">${icon('lock')}No sign-up. No password to an online account.</div></div>`}
function special(){if(screen==='empty')return header('Documents','A private home for your essentials.',true)+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('folder')}</div><h3>Your important things,<br>all in one place.</h3><p>Add an ID, licence or insurance document as a photo or PDF. Available even when you’re offline.</p></div><div class="notice">${icon('shield')}Encrypted on this phone. No account needed.</div></div>${footer('Add your first document','go:add')}`+nav();
if(screen==='present')return header('Show at counter','Document shown at full brightness')+`<div class="content">${paper(current(),back)}</div><div class="action-footer">${button('Flip','flip','secondary')}${button('Done',current().pdf?'go:pdf':'go:document','primary')}</div>`;
if(screen==='lock')return `<div class="content" style="display:flex;align-items:center;justify-content:center"><div class="hero-center"><div class="hero-icon">${icon('lock')}</div><h3>Your documents.<br>For your eyes only.</h3><p>Unlock Doc Keeper with your fingerprint, face or device passcode.</p></div></div>${footer('Unlock Doc Keeper','unlock')}`;
if(screen==='boot')return `<div class="content"><div class="hero-center" style="padding-top:180px"><div class="hero-icon">${icon('shield')}</div><h3>Doc Keeper</h3><div class="loading-ring"></div><p>Opening your private vault…</p>${button('Continue demo','go:home','secondary')}</div></div>`;
if(screen==='recovery')return header('Recover your vault')+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('lock')}</div><h3>We can’t open<br>this vault.</h3><p>The encryption key is no longer available on this device. You can restore an exported backup to recover your documents.</p></div><div class="notice warning">${icon('shield')}Starting again removes the inaccessible documents from this phone.</div>${button('Try again','retry','secondary')}${button('Start fresh','start-fresh','danger')}</div>${footer('Restore from backup','recover')}`;
if(screen==='crash')return header('Welcome back')+`<div class="content"><div class="hero-center"><div class="hero-icon">${icon('doc')}</div><h3>Doc Keeper closed<br>unexpectedly.</h3><p>You can help by sharing a technical report. It contains app details and recent activity, never your documents or their text.</p></div>${button('Review report','go:problems','secondary')}</div><div class="action-footer">${button('Not now','go:home','secondary')}${button('Share report','report')}</div>`;
if(screen==='problems')return header('Problems','You choose what to share.')+`<div class="content"><div class="notice">${icon('doc')}<span><strong>Unexpected close · Today, 09:12</strong>A technical report is available on this phone.</span></div><h3>What the report includes</h3><p class="muted">App version, phone model, the error and recent app log lines. Never your documents, their names or their text.</p><div class="pdf-page" style="min-height:160px"><strong>Sample report</strong><p>Doc Keeper 1.0.0<br>Android 16<br>Opening document failed<br>Technical details available</p></div>${button('Email report','report','secondary')}${button('Dismiss report','dismiss-report','danger')}</div>${footer('Share technical report','report')}`;
return ''}
function render(){const v=variants.find(v=>v.id===variant);let url=new URL(location.href);url.searchParams.set('variant',variant);url.searchParams.set('screen',screen);if(baseScreen)url.searchParams.set('from',baseScreen);else url.searchParams.delete('from');history.replaceState({},'',url);document.title=`${screens.find(s=>s[0]===screen)?.[1]} · ${v.short} · Doc Keeper prototypes`;
document.querySelector('#directions').innerHTML=variants.map((v,i)=>`<button class="direction ${variant===v.id?'active':''}" data-variant="${v.id}" aria-pressed="${variant===v.id}"><span class="dot" style="--dot:${v.colors[2]}"></span><span>${i+1}. ${v.short}<small>${v.tag}</small></span></button>`).join('');
document.querySelector('#screens').innerHTML=screens.map(([s,l])=>`<button data-go="${s}" class="${s===screen?'active':''}" ${s===screen?'aria-current="page"':''}>${l}</button>`).join('');document.querySelector('#screen-count').textContent=screens.length;
document.querySelector('#study-label').textContent=`Study ${variants.indexOf(v)+1} of ${variants.length} · ${screens.find(s=>s[0]===screen)?.[1]}`;document.querySelector('#study-title').textContent=v.name;document.querySelector('#study-description').textContent=v.description;document.querySelector('#principle-title').textContent=v.principle;document.querySelector('#principle-copy').textContent=v.copy;document.querySelector('#palette').innerHTML=v.colors.map(c=>`<span title="${c}" style="background:${c}"></span>`).join('');document.querySelector('#variant-label').textContent=`${variants.indexOf(v)+1} / ${variants.length} · ${v.short}`;
const device=document.querySelector('#device');device.dataset.variant=variant;device.classList.toggle('present-mode',screen==='present');
const output=renderScreen(screen);document.querySelector('#app').innerHTML=baseScreen?`<div class="app-base" inert aria-hidden="true">${renderScreen(baseScreen)}</div><button class="sheet-scrim" data-action="close-sheet" aria-label="Close sheet"></button><section class="bottom-sheet" role="dialog" aria-modal="true" aria-label="${esc(screens.find(s=>s[0]===screen)?.[1])}"><div class="sheet-grab" aria-hidden="true"></div>${output}</section>`:output;document.querySelector('#state').textContent=JSON.stringify({variant,screen,baseScreen,documents:docs.length,notes:notes.length,selected,filter,side:back?'back':'front',importStep,settings},null,2);if(baseScreen)document.querySelector('.bottom-sheet .icon-button')?.focus()}
function renderScreen(which){const active=screen;screen=which;const output=screen==='home'?(docs.length?home():specialEmpty()):['add','edit','share'].includes(screen)?editor():screen==='document'?documentView():screen==='pdf'?pdfView():screen==='notes'?notesView():screen==='note'?noteView():['tags','folders'].includes(screen)?organise(screen):screen==='settings'?settingsView():screen==='export'?exportView():screen==='import'?importView():screen==='paywall'?paywall():screen==='privacy'?privacy():special();screen=active;return output}
function specialEmpty(){const old=screen;screen='empty';const html=special();screen=old;return html}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3200)}
function modal(title,body,actions){const d=document.querySelector('#dialog');d.innerHTML=`<h2>${title}</h2>${body}${actions}`;d.showModal();d.querySelector('button')?.focus()}
function closeModal(){document.querySelector('#dialog').close()}
function cycle(n){setVariant(variants[(variants.findIndex(v=>v.id===variant)+n+variants.length)%variants.length].id)}
function newDocument(){documentDraft=null;go('add')}
function action(a){if(a.startsWith('go:')){const dest=a.slice(3);if(dest==='add')return newDocument();if(dest==='edit')documentDraft=null;return go(dest)}if(a.startsWith('info:'))return toast(a.slice(5));if(a.startsWith('upload:')){const side=a.slice(7);return modal('Choose '+(side==='PDF'?'a PDF':side.toLowerCase()),'<p>Prototype: try a sample instead of accessing your camera or files.</p>',button('Use sample '+side,'sample:'+side)+button('Cancel','close','secondary'))}if(a.startsWith('sample:')){closeModal();captureDraft();documentDraft={...documentDraft,name:documentDraft?.name||'New document',tag:documentDraft?.tag||'ID'};render();return toast(a.slice(7)+' sample attached')}
if(a.startsWith('view:')){details=a==='view:details';return render()}if(a.startsWith('pdf:')){pdfPage=Math.max(1,Math.min(4,pdfPage+(a.endsWith('next')?1:-1)));return render()}if(a==='cover')return toast('Page '+pdfPage+' selected as cover in demo');if(a==='flip'){back=!back;render();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelector('#app .paper')?.animate([{transform:screen==='present'?'rotate(90deg) scale(1.25) rotateY(-18deg)':'perspective(700px) rotateY(-18deg)',opacity:.45},{transform:screen==='present'?'rotate(90deg) scale(1.25)':'perspective(700px) rotateY(0)',opacity:1}],{duration:340,easing:'cubic-bezier(.2,.8,.2,1)'});return}
if(a==='pin'){current().pinned=!current().pinned;render();return toast(current().pinned?'Pinned for quick access':'Document unpinned')}
if(a==='share-document')return modal('Share document','<p>Choose a format. Sharing in this prototype is simulated.</p>',button('Share photo','share-photo')+button('Share as PDF','share-pdf','secondary')+button('Cancel','close','secondary'));
if(['share-photo','share-pdf','report'].includes(a)){if(document.querySelector('#dialog').open)closeModal();return toast('Demo only: '+(a==='report'?'technical report prepared':a==='share-photo'?'photo prepared for sharing':'PDF prepared for sharing'))}
if(a==='save-text'){const blob=new Blob([current().name+'\n'+current().person+'\n'+current().number],{type:'text/plain'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='sample-document-text.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Fictional document text downloaded')}
if(a==='save-document'){captureDraft();if(!documentDraft.name?.trim()){document.querySelector('[name="name"]').focus();return toast('Give your document a name first')}if(screen==='edit'){Object.assign(current(),{name:documentDraft.name,tag:documentDraft.tag,expiry:documentDraft.expiry||current().expiry})}else {selected=Math.max(...docs.map(d=>d.id),0)+1;docs.push({...originalDocs[0],id:selected,name:documentDraft.name,tag:documentDraft.tag,expiry:documentDraft.expiry||'Not set',pinned:false})}documentDraft=null;go('document');return toast('Document kept in this demo')}
if(a==='delete-document')return modal('Delete this document?','<p>This removes the document from this sample library.</p>',button('Cancel','close','secondary')+button('Delete document','confirm-delete-document','danger'));
if(a==='confirm-delete-document'){docs=docs.filter(d=>d.id!==selected);closeModal();go('home');return toast('Sample document deleted')}
if(a==='new-note'){selectedNote=notes.length;noteDraft={title:'',body:''};return go('note')}
if(a==='save-note'){captureDraft();notes[selectedNote]={...notes[selectedNote],...noteDraft};noteDraft=null;go('notes');return toast('Note saved in demo')}
if(a==='pin-note'){captureDraft();if(!notes[selectedNote])notes[selectedNote]={...noteDraft};notes[selectedNote].pinned=!notes[selectedNote].pinned;render();return toast(notes[selectedNote].pinned?'Note pinned':'Note unpinned')}
if(a==='delete-note')return modal('Delete this note?','<p>The sample note will be removed from this demo.</p>',button('Cancel','close','secondary')+button('Delete note','confirm-delete-note','danger'));
if(a==='confirm-delete-note'){notes.splice(selectedNote,1);noteDraft=null;closeModal();go('notes');return toast('Note deleted')}
if(a.startsWith('new:')){let kind=a.slice(4);return modal('Create '+(kind==='tags'?'tag':'folder'),`<form id="name-form">${field('Name','name')}</form>`,button('Cancel','close','secondary')+button('Create','create:'+kind))}
if(a.startsWith('create:')){let value=document.querySelector('#name-form input').value.trim();if(!value)return toast('Enter a name first');let items=a.endsWith('tags')?tags:folders;if(items.includes(value))return toast('That name is already in use');items.push(value);closeModal();render();return toast('Created '+value)}
if(a.startsWith('manage:')){let [,kind,index]=a.split(':'),items=kind==='tags'?tags:folders;return modal(esc(items[index]),`<p>Rename this ${kind==='tags'?'tag':'folder'} or remove it. Documents stay in the library.</p><form id="name-form">${field('Name','name',items[index])}</form>`,button('Save name',`rename:${kind}:${index}`)+button('Remove',`remove:${kind}:${index}`,'danger')+button('Cancel','close','secondary'))}
if(a.startsWith('rename:')||a.startsWith('remove:')){let [op,kind,index]=a.split(':'),items=kind==='tags'?tags:folders,old=items[index],name=document.querySelector('#name-form input').value.trim();if(op==='rename'){if(!name)return toast('Enter a name first');items[index]=name;if(kind==='tags')docs.forEach(d=>{if(d.tag===old)d.tag=name})}else{items.splice(index,1);if(kind==='tags')docs.forEach(d=>{if(d.tag===old)d.tag='Untagged'})}closeModal();render();return toast(op==='rename'?'Name updated':'Removed; documents kept')}
if(a==='export-backup'){const f=new FormData(document.querySelector('#backup-form'));if(String(f.get('passphrase')).length<8)return toast('Use at least 8 characters');if(f.get('passphrase')!==f.get('confirm'))return toast('The passphrases do not match');return modal('Backup preview complete','<p>The passphrases match. In the real app, you would now choose where to save an encrypted backup. No backup file or encryption is created by this design study.</p>',button('Done','close'))}
if(a==='pick-backup'){importStep=1;return render()}if(a==='unlock-backup'){if(document.querySelector('[name="passphrase"]').value!=='keeperdemo')return toast('Try the demo passphrase: keeperdemo');importStep=2;return render()}if(a==='merge-backup'){go('home');importStep=0;return toast('Sample backup checked: duplicates skipped')}
if(a==='replace-backup')return modal('Replace the sample library?','<p>Your current demo documents and notes will be replaced with the sample backup.</p>',button('Cancel','close','secondary')+button('Replace sample library','confirm-replace','danger'));
if(a==='confirm-replace'){docs=structuredClone(originalDocs);notes=[{title:'Restored note',body:'This note came from the sample backup.'}];closeModal();importStep=0;go('home');return toast('Sample backup restored')}
if(a==='check-price')return modal('Store price preview','<p>The real app retrieves a local price from the app store. No live price is shown here and no purchase will be made.</p>',button('Done','close'));
if(a==='restore-purchase')return toast('Demo: no store purchase is connected');if(a==='updates')return modal('App updates','<p>Version 1.0.0 · Prototype only</p><p>Updates are downloaded only when you choose. Your documents stay on the phone.</p>',button('Check for updates','check-update')+button('Done','close','secondary'));if(a==='check-update'){closeModal();return toast('Simulated check complete · Demo is up to date')}
if(a==='dismiss-report'){go('settings');return toast('Sample report dismissed')}
if(a==='unlock'){go('home');return toast('Demo unlocked · Device authentication is simulated')}
if(a==='retry'){go('boot');return toast('Demo retry: continue to open the sample vault')}
if(a==='recover'||a==='start-fresh')return modal(a==='recover'?'Restore from backup?':'Start a new vault?','<p>The real app removes inaccessible documents before continuing. Only sample data is affected here.</p>',button('Cancel','close','secondary')+button(a==='recover'?'Continue to import':'Start fresh','confirm:'+a,'danger'));
if(a==='confirm:recover'){closeModal();importStep=0;return go('import')}if(a==='confirm:start-fresh'){closeModal();docs=[];return go('empty')}
if(a==='close-sheet')return closeSheet();if(a==='clear-search'){query='';filter='All';return render()}if(a==='close')return closeModal();}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.variant)return setVariant(el.dataset.variant);if(el.dataset.go){if(el.dataset.go==='add')return newDocument();if(el.dataset.go==='edit')documentDraft=null;return go(el.dataset.go)}if(el.dataset.present){selected=Number(el.dataset.present);go('present');return}if(el.dataset.open){selected=Number(el.dataset.open);go(current().pdf?'pdf':'document');return}if(el.dataset.note){selectedNote=Number(el.dataset.note);noteDraft=null;return go('note')}if(el.dataset.filter){filter=el.dataset.filter;return render()}if(el.dataset.action)action(el.dataset.action)});
document.addEventListener('input',e=>{if(e.target.id==='search'){const start=e.target.selectionStart;query=e.target.value;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(start,start)}if(e.target.dataset.setting){settings[e.target.dataset.setting]=e.target.checked;document.querySelector('#state').textContent=JSON.stringify({variant,screen,settings},null,2)}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='document-form')action('save-document');if(e.target.id==='note-form')action('save-note')});
document.querySelector('#previous').onclick=()=>cycle(-1);document.querySelector('#next').onclick=()=>cycle(1);document.addEventListener('keydown',e=>{if(document.querySelector('#dialog').open)return;if(e.key==='Escape'&&baseScreen){e.preventDefault();return closeSheet()}if(baseScreen){if(e.key==='Tab'){const sheet=document.querySelector('.bottom-sheet'),items=[...sheet.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]')],first=items[0],last=items.at(-1);if(first&&(!sheet.contains(document.activeElement)||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first).focus()}}return}if(e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();cycle(e.key==='ArrowLeft'?-1:1)}});
document.querySelector('#reset').onclick=()=>{docs=structuredClone(originalDocs);notes=[{title:'For the next trip',body:'Passport, residency and travel insurance.\n\nCheck the expiry dates before booking.',pinned:true},{title:'Insurance helpline',body:'Keep the policy number handy when calling. Coverage renews in March.'}];folders=['Personal','Travel','Home'];tags=['ID','Insurance','Home','Travel'];settings={lock:true,brightness:true,swipe:false,blur:false};selected=1;selectedNote=0;query='';filter='All';importStep=0;pdfPage=1;documentDraft=null;noteDraft=null;go('home');toast('Demo reset')};
render();
